questionvariables.text:
/* Fonction utilitaire */
ri(a,b) := a + rand(b - a + 1)$ 
/* Génération des coordonnées des 3 points */
xa: ri(-3,3)$ ya: ri(-3,3)$ za: ri(-3,3)$ xb: ri(-3,3)$ yb: ri(-3,3)$ zb: ri(-3,3)$ xc: ri(-3,3)$ yc: ri(-3,3)$ zc: ri(-3,3)$ 
/* Coordonnées des vecteurs AB et AC */
ux: xb-xa$ uy: yb-ya$ uz: zb-za$ vx: xc-xa$ vy: yc-ya$ vz: zc-za$ 
/* Coordonnées du produit vectoriel AB ^ AC */
cx: uy*vz - uz*vy$ cy: uz*vx - ux*vz$ cz: ux*vy - uy*vx$ 
/* Carré de la norme du produit vectoriel */
norme_carre: cx^2 + cy^2 + cz^2$ 
/* Sécurité : on s'assure que les points ne sont pas alignés (norme_carre != 0) */
while norme_carre = 0 do (
    xb: ri(-3,3), yb: ri(-3,3), zb: ri(-3,3),
    xc: ri(-3,3), yc: ri(-3,3), zc: ri(-3,3),
    ux: xb-xa, uy: yb-ya, uz: zb-za,
    vx: xc-xa, vy: yc-ya, vz: zc-za,
    cx: uy*vz - uz*vy,
    cy: uz*vx - ux*vz,
    cz: ux*vy - uy*vx,
    norme_carre: cx^2 + cy^2 + cz^2
)$ 
/* Valeurs attendues */
aire_exact: sqrt(norme_carre)/2$ aire_arr: 1.00*(round(float(aire_exact)*100)/100)$ sqrt_arr: round(float(sqrt(norme_carre))*100)/100$ 
/* Erreurs classiques */
err_para_arr: round(float(sqrt(norme_carre))*100)/100$ err_sans_rac_arr: round(float(norme_carre/2)*100)/100$ aire_2d: abs(ux*vy - uy*vx)/2$ err_2d_arr: round(float(aire_2d)*100)/100$
